// Demo: Harness Design — confidence interval over 1 runs
var runs=[];for(var i=0;i<1;i++){runs.push(100+((i*37+1)%21)-10);}
runs.sort(function(a,b){return a-b;});
var mean=runs.reduce(function(a,b){return a+b;},0)/runs.length;
var sd=Math.sqrt(runs.reduce(function(a,b){return a+(b-mean)*(b-mean);},0)/runs.length);
console.log('technique: Harness Design');console.log('runs: '+runs.length+', mean: '+mean.toFixed(1)+' ms, sd: '+sd.toFixed(1));
console.log('95% CI: ['+(mean-1.96*sd/Math.sqrt(runs.length)).toFixed(1)+', '+(mean+1.96*sd/Math.sqrt(runs.length)).toFixed(1)+']');

