// Demo: Regression Detection — regression detection vs baseline
var base=[];for(var i=0;i<16;i++){base.push(100+((i*13+3)%11)-5);}
var cur=base.map(function(b){return b*1.06;});
function mean(a){return a.reduce(function(x,y){return x+y;},0)/a.length;}
var delta=(mean(cur)-mean(base))/mean(base);
console.log('technique: Regression Detection');console.log('baseline mean: '+mean(base).toFixed(1)+' ms, current mean: '+mean(cur).toFixed(1)+' ms');
console.log('delta: '+(delta*100).toFixed(1)+'% -> '+(delta>0.03?'REGRESSION — block the merge':'within noise — allow'));

