// Demo: Noisy-Neighbor Isolation — outlier rejection
var runs=[];for(var i=0;i<59;i++){runs.push(100+((i*29+9)%15));}
runs.push(500,620);
var s=runs.slice().sort(function(a,b){return a-b;});
var q1=s[Math.floor(s.length*0.25)],q3=s[Math.floor(s.length*0.75)],iqr=q3-q1;
var clean=s.filter(function(x){return x>=q1-1.5*iqr&&x<=q3+1.5*iqr;});
console.log('technique: Noisy-Neighbor Isolation');console.log('raw runs: '+runs.length+', after IQR filter: '+clean.length);
console.log('rejected '+ (runs.length-clean.length) +' outliers — median now '+(clean[Math.floor(clean.length/2)])+' ms');

